import pathlib,json,shutil,subprocess
r={'access_evidence':{},'installed_tools':{},'publication_verified':False}
for n in ['distribution-access.json','hosting-access-probe.txt']:
 p=pathlib.Path('products/research')/n
 r['access_evidence'][n]=p.read_text()[:18000] if p.exists() else 'MISSING'
for n in ['gh','vercel','netlify','node','npm']:
 r['installed_tools'][n]=bool(shutil.which(n))
if shutil.which('gh'):
 t=subprocess.run(['gh','auth','status'],capture_output=True,text=True,timeout=30)
 r['github_auth']={'returncode':t.returncode,'output':(t.stdout+t.stderr)[:4000]}
r['limitations']='Installed tools do not establish hosting authorization. No publication or payment access is inferred.'
p=pathlib.Path('products/research/distribution-next-step.json');p.write_text(json.dumps(r,indent=2));print(json.dumps(r))
